insert into public.kpi_project_classification_periods(tenant_id,project_reference,project_name,cost_center,cost_center_name,business_group,registrations,valid_from,source) select '944597b6-9c46-4bef-998d-f19e23c4245b',project_reference,project_name,cost_center,cost_center_name,business_group,registrations,'2025-09-01',source from input;
insert into public.kpi_business_groups(tenant_id,name,code) select distinct tenant_id,business_group,'source_group_'||substr(md5(business_group),1,12) from public.kpi_project_classification_periods where tenant_id='944597b6-9c46-4bef-998d-f19e23c4245b' and business_group is not null on conflict(tenant_id,name) do nothing;
